  [1, 5, 9, 13, 17, 21].map(x => `<rect x="${x}" y="1" width="3" height="3"/>`).join("") +
  [3, 7, 11, 15, 19].map(x => `<rect x="${x}" y="6.5" width="3" height="3"/>`).join("") +
  '<rect x="6" y="12" width="14" height="3"/></svg>';
